function updateMhDirectHelp(root,group){
 var panel=root.querySelector('.mh-direct-help[data-help-group="'+group+'"]');if(!panel)return;
 var id=selected[group];panel.hidden=!id;if(!id)return;
 var stage=mhHelpStages[group]||0, phrases=mhDirectPhrases(group,id);
 panel.querySelector('.mh-direct-phrase').textContent=stage===0?phrases[1]:phrases[2];
 panel.querySelector('.mh-direct-next').textContent=stage===0?'Comment continuer ?':'Masquer l’amorce suivante';
}

function recap(){return groups.map(function(g){var match=g.items.find(function(it){return it[0]===selected[g.key];});return '<span>'+esc(match?match[1]:'À inventer')+'</span>';}).join('');}
/* Amorces selon les trois illustrations choisies : aides progressives, sans écriture automatique. */
var whoGrammar={fille:['une fille','elle'],garcon:['un garçon','il'],chevalier:['un chevalier','il'],princesse:['une princesse','elle'],sorcier:['un sorcier','il'],dragon:['un dragon','il'],renard:['un renard','il'],chien:['un chien','il']};
var whereGrammar={chateau:'près d’un château',foret:'dans une forêt',montagne:'sur une montagne',village:'dans un village',grotte:'près d’une grotte',ile:'sur une île inconnue'};
var eventGrammar={porte:'voit une porte mystérieuse s’ouvrir',tresor:'découvre quelque chose d’étrange',rencontre:'fait une rencontre surprenante',voyage:'commence un voyage inattendu',mystere:'remarque un détail mystérieux',aventure:'vit une aventure extraordinaire'};
var helpStage=0;
function writingStarter(stage){
 var w=whoGrammar[selected.who],loc=whereGrammar[selected.where],act=eventGrammar[selected.what];
 if(!w&&!loc&&!act)return stage===1?'Un jour…':'Un jour, un personnage arrive dans un lieu inconnu. Soudain…';
 var subject=w?w[0]:'un personnage';var pronoun=w?w[1]:'il ou elle';
 if(stage===1)return 'Un jour, '+subject+'…';
 var first='Un jour, '+subject+(loc?' se promène '+loc:' part à l’aventure')+'.';
 return first+'\nSoudain, '+(w?pronoun:'le personnage')+' '+(act||'aperçoit quelque chose d’étrange')+'…';
}
