 var items=[{id:2,img:'graine-fleur.jpg',alt:'Un tournesol a fleuri'},{id:0,img:'graine-planter.jpg',alt:'Un garçon plante une graine'},{id:1,img:'graine-arroser.jpg',alt:'Le garçon arrose une jeune plante'}];
 var storeKey='mh-writing-v1:'+student()+':images-petite-graine';
