 var correct=false;
 function redraw(){root.querySelectorAll('[data-scene]').forEach(function(b){var v=Number(b.dataset.scene),index=state.order.indexOf(v);b.classList.toggle('selected',index!==-1);b.setAttribute('aria-pressed',String(index!==-1));b.querySelector('.mh-graine-rank').textContent=index===-1?'':'Choix '+(index+1);});root.querySelector('#mh-graine-writing').hidden=!correct;}
 root.querySelectorAll('[data-scene]').forEach(function(btn){btn.addEventListener('click',function(){var id=Number(btn.dataset.scene),at=state.order.indexOf(id);if(at!==-1)state.order.splice(at,1);else if(state.order.length<3)state.order.push(id);correct=false;root.querySelector('#mh-graine-feedback').textContent='';redraw();persist();});});
