 root.querySelectorAll('[data-chien-scene]').forEach(function(btn){btn.addEventListener('click',function(){var id=Number(btn.dataset.chienScene),pos=state.order.indexOf(id);if(pos>=0)state.order.splice(pos,1);else if(state.order.length<4)state.order.push(id);verified=false;root.querySelector('#mh-chien-feedback').textContent='';redraw();persist();});});
